query:
    query getProduct  {
      product(id: "gid://shopify/Product/7521406484551") {

          id
title
tags
handle
totalInventory
description
descriptionHtml
onlineStoreUrl
productType
vendor
availableForSale
requiresSellingPlan
sellingPlanGroups (first: 20) {
    edges {
        node {
            name
            sellingPlans (first: 20) {
                edges {
                    node {
                        id
                        name
                        description
                        recurringDeliveries
                    }
                }
            }
        }
    }
}
media (first: 250) {
    edges {
        node {
            mediaContentType
            ... on Video {
                id
                mediaContentType
                sources {
                    url
                    height
                    format
                    width
                }
                previewImage {
                    originalSrc: url (transform: {})
                }
            }
            ... on MediaImage {
                id
                mediaContentType
                image {
                    height
                    id
                    originalSrc: url (transform: {})
                    width
                    url (transform: {maxHeight: 500, maxWidth: 500})
                }
            }
        }
    }
}
priceRange {
    maxVariantPrice {
        amount
        currencyCode
    }
    minVariantPrice {
        amount
        currencyCode
    }
}
compareAtPriceRange {
    maxVariantPrice {
        amount
        currencyCode
    }
    minVariantPrice {
        amount
        currencyCode
    }
}
options {
    id
    name
    values
}
appmaker_hide_product_status: metafield (namespace: "appmaker", key: "hide_product_status") {
    value
}
variants (first: 250) {
    pageInfo {
        hasNextPage
        hasPreviousPage
    }
    edges {
        node {
            sellingPlanAllocations (first: 10) {
                edges {
                    node {
                        sellingPlan {
                            id
                            name
                            options {
                                name
                                value
                            }
                        }
                        priceAdjustments {
                            price {
                                amount
                                currencyCode
                            }
                            compareAtPrice {
                                amount
                                currencyCode
                            }
                            perDeliveryPrice {
                                amount
                                currencyCode
                            }
                            unitPrice {
                                amount
                                currencyCode
                            }
                        }
                    }
                }
            }
            availableForSale
            currentlyNotInStock
            quantityAvailable
            sku
            id
            title
            selectedOptions {
                name
                value
            }
            image {
                src: url (transform: {})
                url (transform: {maxHeight: 500, maxWidth: 500})
            }
            price {
                amount
                currencyCode
            }
            compareAtPrice {
                currencyCode
                amount
            }
            custom_product_mobile_price: metafield (key: "product_mobile_price", namespace: "custom") {
                value
            }
            custom_custom_variant_total_quantity: metafield (key: "custom_variant_total_quantity", namespace: "custom") {
                value
            }
        }
    }
}
images (first: 250) {
    pageInfo {
        hasNextPage
        hasPreviousPage
    }
    edges {
        node {
            altText
            src: url (transform: {})
            height
            width
            url (transform: {maxHeight: 500, maxWidth: 500})
        }
    }
}
